from lib import *
S = SS('m37')
steps = [
    step("50 万个文档,按 ts 排序(ts_1__id_1 索引),每页 20 条:skip 0 要 0.3 ms(检查 20 个键);skip 1,000 0.4 ms(1,020 个键);skip 10,000 2.2 ms(10,020);skip 100,000 18 ms(100,020);skip 400,000 74 ms(400,020)。读取的文档始终是 20 个,耗时随被跳过的索引键线性增长。", t=tl(S(1)), mark=lidx(S(1), '400,000', '100,000'), done=lidx(S(1), '         0', '1,000'), b=bars([['skip 0', 0.3, '0.3 ms'], ['skip 10,000', 2.2, '2.2 ms'], ['skip 100,000', 18, '18 ms'], ['skip 400,000', 74, '74 ms']], 74, mark=[3], done=[0, 1, 2]), kv=KV([['检查的键', 'skip + 20'], ['读取的文档', '始终 20'], ['耗时', '随 skip 线性增长']], ['检查的键'])),
    step("范围分页:记住上一页最后一条的 (ts, _id),条件 {$or: [{ts: {$gt}}, {ts, _id: {$gt}}]} 加 limit(20):不管上一页最后一条的 _id 是 0、1,000、10,000、100,000 还是 400,000,每页都只检查 20 个键、读 20 个文档,耗时 0.2~0.4 ms。", t=tl(S(2)), mark=lidx(S(2), '400,000'), done=lidx(S(2), '         0', '100,000'), kv=KV([['每页代价', '与翻到第几页无关'], ['检查的键 / 文档', '始终 20 / 20']], ['每页代价'])),
    step("explain skip(100000).limit(20):计划是 LIMIT > FETCH > SKIP > IXSCAN,检查 100,020 个键,只读取 20 个文档(SKIP 在 FETCH 之下,被跳过的只读索引键);只要索引里的字段 {_id: 1, ts: 1} 时是覆盖查询,键 100,020、文档 0——但 100,000 个键仍然要扫。", t=tl(S(3)), mark=lidx(S(3), 'keysExamined: 100020', 'keys: 100020'), done=lidx(S(3), 'LIMIT > FETCH > SKIP > IXSCAN', 'docsExamined: 20', 'docs: 0'), kv=KV([['SKIP 在 FETCH 之下', '不读被跳过的文档'], ['但键', '仍要扫 skip + limit 个']], ['SKIP 在 FETCH 之下'])),
    step("排序键不唯一时必须带平局打破字段:按 ts 排序取 15 条,最后一条 _id=1014、ts=101,而这个 ts 共有 10 个文档;只用 ts > 101 作为下一页条件,下一页从 _id=1020 开始,丢掉了 5 个 ts 相同的文档(1015~1019);用 (ts, _id) 作条件,下一页第一条是 _id=1015,紧接着,一个不丢。", t=tl(S(4)), mark=lidx(S(4), '丢掉了 5 个'), done=lidx(S(4), '_id=1015'), kv=KV([['只用 ts', '丢掉 5 个同 ts 的文档'], ['(ts, _id)', '一个不丢']], ['(ts, _id)'])),
    step("翻页期间有新数据:最新在前展示,第 1 页是 1000…981;之后插入 10 条新数据(1001~1010);skip(20) 的第 2 页是 990…971,与第 1 页重复 10 条;范围方式({_id: {$lt: 981}})的第 2 页是 980…961,重复 0 条。", t=tl(S(5)), mark=lidx(S(5), '重复的条数 10'), done=lidx(S(5), '第 1 页', '重复的条数 0'), b=bars([['skip 方式第 2 页重复', 10, '10 条'], ['范围方式第 2 页重复', 0, '0 条']], 10, mark=[0], done=[1]), kv=KV([['skip', '新数据插在前面,整体后移,重复'], ['范围', '从上一页的位置继续,不受影响']], ['skip'])),
    step("总页数要的总数:countDocuments({}) 49 ms(要数文档);estimatedDocumentCount() 0.1 ms(读元数据);countDocuments({user: 5})(无索引的过滤条件)55 ms。", t=tl(S(6)), mark=lidx(S(6), 'countDocuments({}) 49 ms'), done=lidx(S(6), 'estimatedDocumentCount()'), kv=KV([['countDocuments', '49 ms(50 万个文档)'], ['estimatedDocumentCount', '0.1 ms,但没有过滤条件']], ['estimatedDocumentCount'])),
]
A = mkartm('m37', 37, 'MongoDB,分页,skip,范围分页,游标,性能,真实验证,动画演示',
    '实测 skip 大偏移的代价与范围分页:50 万个文档上 skip 400,000 要 74 ms、检查 400,020 个键,范围分页每页恒定 0.2~0.4 ms;SKIP 在 FETCH 之下,只读索引键不读文档;排序键不唯一要带 _id 平局打破;翻页期间有新数据时 skip 重复 10 条而范围分页不重复;count 的两种代价。',
    'skip 到底慢在哪?范围分页怎么写才不会丢数据、不会重复?这篇用 50 万个文档对比两种分页的检查量、耗时和一致性。',
    [('74 ms', 'skip 400,000 取 20 条的耗时;范围分页恒定 0.2 ms'), ('100,020 对 20', 'skip 100,000 时检查的键数与读取的文档数'), ('10 条', '翻页期间插入 10 条新数据后,skip 方式第 2 页与第 1 页重复的条数(范围方式 0 条)')],
    [('skip 的代价', '<p>skip N 要扫过 N 个索引键:skip 400,000 检查 400,020 个键、74 ms;读取的文档只有 20 个,代价在索引键上。</p>'),
     ('范围分页', '<p>记住上一页最后一条的排序键,下一页从它后面开始,每页只检查 20 个键,与翻到第几页无关。</p>'),
     ('explain', '<p>计划里 <code>SKIP</code> 在 <code>FETCH</code> 之下,被跳过的文档不读;覆盖查询时文档数为 0,但被跳过的键仍要扫。</p>'),
     ('平局打破', '<p>排序键不唯一时,条件必须带 <code>_id</code> 之类唯一字段,只用 <code>ts &gt; 上一页最后的 ts</code> 会丢掉同一个 ts 的其余文档。</p>'),
     ('一致性', '<p>翻页期间有新数据写入,skip 方式整体后移,第 2 页重复了第 1 页的 10 条;范围方式不受影响。</p>'),
     ('总数', '<p><code>countDocuments</code> 要数文档(50 万个 49 ms),<code>estimatedDocumentCount</code> 读元数据(0.1 ms)但不能带过滤条件。</p>')],
    steps,
    [ENV_M + '。50 万个文档(ts 每 10 个文档相同);耗时是 pymongo 的 5 次中位数,检查量来自 explain',
     '没有验证:skip 配合 sort 但没有索引时(要全部排序);分片集群上的 skip(每个分片都要取 skip + limit);游标式分页(batchSize、getMore)与分页的区别;降序分页与复合排序方向混合;多排序键的范围条件写法在更复杂场景下的计划'],
    'skip 分页与范围分页')
